def average_past_loop(x: torch.Tensor) -> torch.Tensor:
    """v1: xbow[b, t] = media di x[b, 0..t]. ("bow" = bag of words)"""
    B, T, C = x.shape
    xbow = torch.zeros_like(x)
    for b in range(B):
        for t in range(T):
            xbow[b, t] = x[b, : t + 1].mean(dim=0)  # (t+1, C) → (C,)
    return xbow

